def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

# Primes allowed based on a1 = 2024 = 2^3 * 11 * 23
allowed_primes = {2, 11, 23}

max_diff = -float('inf')
best_pair = None

# Iterate B_a in the range [12025, 20000]
for B_a in range(12025, 20001):
    factors = prime_factorization(B_a)

    is_valid = True
    for p in factors:
        if p not in allowed_primes:
            is_valid = False
            break

    if is_valid:
        # f(0) = 10000 (Max)
        f0 = 10000
        g0 = B_a - f0

        # Check constraints on g(0)
        if 2025 <= g0 <= 10000:
            diff = f0 - g0
            if diff > max_diff:
                max_diff = diff
                best_pair = (f0, g0, B_a)

print(f"Maximum difference found: {max_diff}")
print(f"Corresponding pair (f(0), g(0)): {best_pair}")
